/**
 * Registers the icons the plugin uses, so @iconify/react never fetches an icon from the Iconify
 * CDN at runtime and the plugin works without internet access. (Headlamp itself only bundles
 * the icons of its own UI.)
 *
 * `src/icons/bundle.json` is generated by `scripts/build-icons.mjs` from the "mdi:…" and
 * "simple-icons:…" ids found in `src/`; `npm start`, `build`, `package` and `storybook` run
 * it first. Import this module first in `index.tsx`.
 */
import { addCollection, IconifyJSON } from '@iconify/react';
import bundle from '../icons/bundle.json';

for (const collection of bundle as unknown as IconifyJSON[]) {
  addCollection(collection);
}
